"""Reusable conversions for Meridian CRM 4.2 storage conventions."""

from datetime import date
from decimal import Decimal, ROUND_HALF_UP
from typing import Union

Amount = Union[str, int, float]


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date to ISO format."""
    if yyyymmdd in (None, "", "00000000"):
        return None
    if len(yyyymmdd) != 8 or not yyyymmdd.isascii() or not yyyymmdd.isdigit():
        raise ValueError(f"invalid legacy date: {yyyymmdd!r}")

    parsed = date(
        int(yyyymmdd[0:4]),
        int(yyyymmdd[4:6]),
        int(yyyymmdd[6:8]),
    )
    return parsed.isoformat()


def from_iso(iso: str | None) -> str:
    """Convert an ISO date to legacy YYYYMMDD format."""
    if iso in (None, ""):
        return "00000000"
    if (
        len(iso) != 10
        or iso[4] != "-"
        or iso[7] != "-"
        or not (iso[0:4] + iso[5:7] + iso[8:10]).isascii()
        or not (iso[0:4] + iso[5:7] + iso[8:10]).isdigit()
    ):
        raise ValueError(f"invalid ISO date: {iso!r}")

    parsed = date.fromisoformat(iso)
    return f"{parsed.year:04d}{parsed.month:02d}{parsed.day:02d}"


def yn(char: str | None) -> bool:
    """Convert a legacy Y/N value, treating blank as N."""
    if char == "Y":
        return True
    if char in ("N", "", None):
        return False
    raise ValueError(f"invalid legacy boolean: {char!r}")


def to_minor_units(amount: Amount | None, currency: str | None) -> int:
    """Convert a legacy decimal amount to currency minor units, half-up."""
    if amount in (None, ""):
        return 0

    effective_currency = "USD" if currency in (None, "") else currency
    exponent = 0 if effective_currency == "JPY" else 2
    factor = Decimal(10) ** exponent
    decimal_amount = Decimal(str(amount))
    rounded = (decimal_amount * factor).to_integral_value(
        rounding=ROUND_HALF_UP
    )
    return int(rounded)
